((SELECT id FROM m), 'Signature Pizzas', 1, 'Combo', 'A crowd favorite, loaded with Scorno''s Italian sausage, pepperoni, mushrooms, green peppers, onions, and mozzarella. Add black olives for extra flavor!', 'Large $25 / Medium $23 / Small $20 / Gluten-Free $25', 25, ARRAY[]::text[], 8),
((SELECT id FROM m), 'Signature Pizzas', 1, 'Rosa Margherita', '(NEW) Featuring Scorno''s new signature Rosa Sauce, a rich blend of our alfredo and classic red sauce. Fresh tomatoes and garlic, melted mozzarella, topped with fresh basil for a bold, authentic flavor in every bite.', 'Large $24.50 / Medium $22.50 / Small $20.50 / Gluten-Free $24.50', 24.50, ARRAY[]::text[], 9),
((SELECT id FROM m), 'Signature Pizzas', 1, 'Deluxe', 'A delicious combination of Scorno''s Italian sausage, capicola, pepperoni, mushrooms, red peppers, and mozzarella for a bold, irresistible flavor.', 'Large $26.50 / Medium $24.50 / Small $21.50 / Gluten-Free $26.50', 26.50, ARRAY[]::text[], 10),
((SELECT id FROM m), 'Signature Pizzas', 1, 'All-Meat', 'A flavor-packed combination of Scorno''s Italian Sausage, our famous meatballs, capicola, pepperoni, and mozzarella. Add bacon for the perfect, ultimate indulgence!', 'Large $25.95 / Medium $23.95 / Small $20.95 / Gluten-Free $25.95', 25.95, ARRAY[]::text[], 11),
