((SELECT id FROM m), 'Signature Pizzas', 1, 'Vacco Taco', 'A Midwest favorite! Seasoned taco meat, cheddar/mozzarella blend, taco sauce, crisp lettuce, fresh tomatoes, and a crunchy layer of taco chips.', 'Large $26.95 / Medium $24.95 / Small $21.95 / Gluten-Free $26.95', 26.95, ARRAY[]::text[], 13),
((SELECT id FROM m), 'Signature Pizzas', 1, 'Chick''n Bacon', 'Marinated chicken, crisp applewood bacon, fresh onions, freshly diced tomatoes and your choice of Scorno''s Ranch or Alfredo sauce, topped with mozzarella, creating a mouthwatering bite every time!', 'Large $25.50 / Medium $23.50 / Small $20.50 / Gluten-Free $25.50', 25.50, ARRAY[]::text[], 14),
