((SELECT id FROM m), 'Signature Pizzas', 1, 'Veggie', 'A colorful medley of fresh onions, green peppers, mushrooms, black olives, and roasted red peppers, all topped with mozzarella for a veggie lover''s dream!', 'Large $22.95 / Medium $20.95 / Small $17.95 / Gluten-Free $22.95', 22.95, ARRAY[]::text[], 16),
((SELECT id FROM m), 'Scorno''s Famous Pastas', 2, 'Baked Cavatelli', 'Our best seller! Cavatelli (shell) pasta baked with Scorno''s famous Italian Sausage and Pasta Sauce, topped with cheesy mozzarella. - Add giardiniera for a spicy burst of flavor!', '$17.95', 17.95, ARRAY[]::text[], 17),
