((SELECT id FROM m), 'Scorno''s Famous Pastas', 2, 'Three Cheese Tortellini', 'Delicate pasta filled with ricotta, parmesan, and asiago cheeses, tossed in your choice of Scorno''s original pasta sauce, our alfredo OR our NEW Rosa Sauce! Finished with shaved parmesan.', '$16.75', 16.75, ARRAY[]::text[], 19),
