((SELECT id FROM m), 'Starters', 3, 'Breaded Ravioli', 'Crunchy pockets of pasta stuffed with a savory meat filling, served with Scorno''s rich Pasta Sauce.', '$10.25', 10.25, ARRAY[]::text[], 28),
