INSERT INTO restaurant_menu_items (menu_id, section_name, section_sort_order, item_name, item_description, price, price_numeric, dietary_tags, sort_order) VALUES
((SELECT id FROM m), 'Shareables', 0, 'Bang Bang Shrimp', 'Crispy fried shrimp, house Bang Bang & sesame ginger sauce. Served on a bed of red cabbage.', '$13.99', 13.99, ARRAY[]::text[], 0),
((SELECT id FROM m), 'Shareables', 0, 'Bao Birds', '24-hour brined, all-natural chicken. Each tender piece is fried to a crispy perfection and nestled between fluffy steamed buns. It''s an explosion of flavors with Korean BBQ sauce, sesame ginger, fresh cabbage, cilantro, and green onions.', '$13.99', 13.99, ARRAY[]::text[], 1),
((SELECT id FROM m), 'Shareables', 0, 'Buffalo Chicken Dip', 'Creamy and tangy buffalo sauce loaded with smoked chicken, topped with blue cheese crumbles and green onion. Served with hand-cut tortilla chips and grilled toast points.', '$11.49', 11.49, ARRAY[]::text[], 2),
((SELECT id FROM m), 'Shareables', 0, 'Fried Cheese', 'Crispy Cornflake-Crusted Premium Bacio Mozzarella fried to order for the ultimate cheese stretch! Served with a side of ranch or marinara.', '$11.99', 11.99, ARRAY[]::text[], 3),
((SELECT id FROM m), 'Shareables', 0, 'Garlic Fries', 'Crispy fries dressed in garlic oil, black garlic seasoning, Parmesan and a side of roasted garlic aioli.', '$10.99', 10.99, ARRAY[]::text[], 4),
((SELECT id FROM m), 'Shareables', 0, 'Hummus', 'Edamame hummus with fresh vegetables, house potato chips, and garlic toast points.', '$11.49', 11.49, ARRAY[]::text[], 5),
((SELECT id FROM m), 'Shareables', 0, 'Fried Pickle Dip', 'Creamy dill pickle dip with toasted panko, served with house chips.', '$11.49', 11.49, ARRAY[]::text[], 6),
((SELECT id FROM m), 'Shareables', 0, 'Everything Pretzels', 'Soft pretzel bites with everything seasoning, served with cheese sauce and honey mustard.', '$11.99', 11.99, ARRAY[]::text[], 7),
((SELECT id FROM m), 'Shareables', 0, 'Loaded Birria Fries', 'Crispy fries with birria beef, Oaxaca-Monterey cheese, serrano avocado crema, cilantro, and onion.', '$13.49', 13.49, ARRAY[]::text[], 8),
((SELECT id FROM m), 'Shareables', 0, 'Roasted Brussels', 'Roasted brussels sprouts, jalapeno bacon jam, lemon Parmesan Romano, and toasted breadcrumbs.', '$11.99', 11.99, ARRAY[]::text[], 9),
((SELECT id FROM m), 'Nachos', 1, 'Sheet Ton of Nachos', 'Hand-cut, fried tortilla chips, smothered in shredded cheddar, house cheese sauce, pico de gallo, sour cream, avocado, and red salsa. Add taco beef or chipotle chicken tinga for $3, or birria beef for $4.', '$13.49', 13.49, ARRAY[]::text[], 10),
((SELECT id FROM m), 'Wings & Tendies', 2, 'Traditional Wings', '1lb JUMBO bone in wings, 24-hour brined, smoked and fried to order. Choice of buffalo, char-buffed, lemon pepper, roasted garlic, korean bbq, jerk rub, gochujang, raspberry heat, or house bbq. Served with ranch or blue cheese and rainbow carrots. Add fries, tots, or chips for $2.', '$15.99', 15.99, ARRAY[]::text[], 11),
((SELECT id FROM m), 'Wings & Tendies', 2, 'BONELESS Wings', '3/4 lb crispy boneless wings, cooked until golden. Choose to have them plain, char-buffed, or tossed in one of our wing sauces (buffalo, lemon pepper, roasted garlic, korean bbq, jerk rub, gochujang, raspberry heat, house bbq). Served with ranch or blue cheese and rainbow carrots. Add fries, tots, or chips for $2.', '$15.99', 15.99, ARRAY[]::text[], 12),
((SELECT id FROM m), 'Wings & Tendies', 2, 'Chicken Tenders', 'Five chicken tenders. Choose to have them plain, char-buffed, or tossed in one of our wing sauces (buffalo, lemon pepper, roasted garlic, korean bbq, jerk rub, gochujang, raspberry heat, house bbq). Served with ranch or blue cheese and rainbow carrots. Add fries, tots, or chips for $2.', '$14.99', 14.99, ARRAY[]::text[], 13),
